        text: '"我师父常说，修仙如逆水行舟，不进则退。"司徒卿釜目光坚定："这数十年来，我从未有一日懈怠。即便资质平庸，我也要用勤补拙。天道酬勤，我相信终有一日，我能走出属于自己的道。" 这便是修仙界的法则，残酷而真实。',
